5	/**
6	 * iHymns — MusicBrainz-Style External Links Migration (#833)
7	 *
8	 * Copyright (c) 2026 iHymns. All rights reserved.
9	 *
10	 * PURPOSE:
11	 * Replaces the three hard-coded songbook URL columns
12	 * (WebsiteUrl / InternetArchiveUrl / WikipediaUrl) AND the existing
13	 * tblCreditPersonLinks free-text-LinkType table with a single
14	 * MusicBrainz-style external-links system covering songs, songbooks
15	 * and credit-people.
16	 *
17	 * Schema (idempotent):
18	 *
19	 *   tblExternalLinkTypes — controlled vocabulary registry. ~37 seed
20	 *     types for hymnology (Hymnary.org, CCLI Songselect, IMSLP,
21	 *     YouTube, Spotify, Internet Archive, Wikipedia, Wikidata,
22	 *     Open Library, OCLC, Cyber Hymnal, LibriVox, MusicBrainz,
23	 *     VIAF, social, …).
24	 *
25	 *   tblSongbookExternalLinks — many-to-many tblSongbooks ↔ link type.
26	 *   tblSongExternalLinks     — many-to-many tblSongs ↔ link type.
27	 *   tblCreditPersonExternalLinks — many-to-many tblCreditPeople ↔ link type.
28	 *
29	 * Each per-entity link row carries Url / Note / SortOrder / Verified
30	 * so a curator can record multiple Internet Archive scans, multiple
31	 * YouTube performances, etc., with per-row context.
32	 *
33	 * Backfills are SEPARATE migrations:
34	 *   - migrate-backfill-songbook-links.php       (#833)
35	 *   - migrate-backfill-credit-person-links.php  (#833)
36	 *
37	 * Legacy reads (songbook URL columns + tblCreditPersonLinks) stay in
38	 * place for one release cycle as fallbacks; later migration drops
39	 * them once the public site has been on the new system.
40	 *
41	 * USAGE:
42	 *   CLI: php appWeb/.sql/migrate-external-links.php
43	 *   Web: /manage/setup-database → "External Links System (#833)"
44	 *
45	 * @migration-adds tblExternalLinkTypes
46	 * @migration-adds tblSongbookExternalLinks
47	 * @migration-adds tblSongExternalLinks
48	 * @migration-adds tblCreditPersonExternalLinks
49	 */
50	
51	if (PHP_SAPI === 'cli') {
52	    if (!function_exists('getDbMysqli')) {
53	        require_once dirname(__DIR__) . '/public_html/includes/db_mysql.php';
54	    }
55	    $isCli = true;
56	} else {
57	    if (!defined('IHYMNS_SETUP_DASHBOARD')) {
58	        if (!function_exists('isAuthenticated')) {
59	            require_once dirname(__DIR__) . '/public_html/manage/includes/auth.php';
60	        }
61	        if (!isAuthenticated()) {
62	            http_response_code(401);
63	            exit('Authentication required.');
64	        }
65	        $u = getCurrentUser();
66	        if (!$u || $u['role'] !== 'global_admin') {
67	            http_response_code(403);
