84	function _migExtLinks_tableExists(\mysqli $db, string $table): bool
85	{
86	    $stmt = $db->prepare(
87	        'SELECT 1 FROM INFORMATION_SCHEMA.TABLES
88	          WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = ? LIMIT 1'
89	    );
90	    $stmt->bind_param('s', $table);
91	    $stmt->execute();
92	    $exists = $stmt->get_result()->fetch_row() !== null;
93	    $stmt->close();
94	    return $exists;
95	}
