97	_migExtLinks_out('External Links migration starting (#833)…');
98	
99	$mysqli = getDbMysqli();
100	if (!$mysqli) {
101	    throw new \RuntimeException('Could not connect to database.');
102	}
103	
104	foreach (['tblSongs', 'tblSongbooks', 'tblCreditPeople'] as $required) {
105	    if (!_migExtLinks_tableExists($mysqli, $required)) {
106	        _migExtLinks_out("ERROR: {$required} not found. Run prerequisite migrations first.");
107	        return;
108	    }
109	}
