111	/* ----------------------------------------------------------------------
112	 * Step 1 — tblExternalLinkTypes (registry)
113	 * ---------------------------------------------------------------------- */
114	if (_migExtLinks_tableExists($mysqli, 'tblExternalLinkTypes')) {
115	    _migExtLinks_out('[skip] tblExternalLinkTypes already present.');
116	} else {
117	    $sql = "CREATE TABLE tblExternalLinkTypes (
118	        Id            INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
119	        Slug          VARCHAR(60)  NOT NULL,
120	        Name          VARCHAR(120) NOT NULL,
121	        Category      ENUM(
122	                          'information', 'listen', 'watch', 'read',
123	                          'sheet-music', 'purchase', 'authority',
124	                          'official', 'social', 'other'
125	                      ) NOT NULL DEFAULT 'other',
126	        UrlPattern    VARCHAR(255) NULL,
127	        IconClass     VARCHAR(60)  NULL,
128	        AppliesTo     SET('song','songbook','person') NOT NULL DEFAULT 'song,songbook,person',
129	        AllowMultiple TINYINT(1)   NOT NULL DEFAULT 1,
130	        IsActive      TINYINT(1)   NOT NULL DEFAULT 1,
131	        DisplayOrder  INT UNSIGNED NOT NULL DEFAULT 0,
132	        CreatedAt     TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
133	
134	        UNIQUE KEY uq_slug   (Slug),
135	        INDEX     idx_active   (IsActive),
136	        INDEX     idx_category (Category, DisplayOrder)
137	    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci";
138	    if (!$mysqli->query($sql)) {
139	        throw new \RuntimeException('CREATE TABLE tblExternalLinkTypes failed: ' . $mysqli->error);
140	    }
141	    _migExtLinks_out('[add ] tblExternalLinkTypes.');
142	}
143	
144	/* ----------------------------------------------------------------------
145	 * Step 2 — Seed link-type registry
146	 *
147	 * INSERT … ON DUPLICATE KEY UPDATE pattern keyed on Slug, so re-runs
148	 * upsert (refreshing Name / Category / IconClass / AppliesTo /
149	 * AllowMultiple / DisplayOrder if the seed list evolves) without
150	 * touching the IsActive column — that's curator-controlled. New
151	 * types added via SQL aren't disturbed by re-running.
152	 * ---------------------------------------------------------------------- */
153	$seedTypes = [
154	    /* slug, name, category, applies_to, allow_multiple, icon, order */
155	    ['official-website',     'Official website',     'official',    'song,songbook,person', 0, 'bi-globe',           10],
156	    ['wikipedia',            'Wikipedia',            'information', 'song,songbook,person', 1, 'bi-wikipedia',       20],
157	    ['wikidata',             'Wikidata',             'information', 'song,songbook,person', 0, 'bi-database',        21],
158	    ['hymnary-org',          'Hymnary.org',          'information', 'song,songbook,person', 0, 'bi-music-note-list', 22],
159	    ['hymnal-plus',          'Hymnal Plus',          'information', 'song,songbook',        0, 'bi-music-note-list', 23],
160	    ['cyber-hymnal',         'The Cyber Hymnal',     'information', 'song,person',          0, 'bi-music-note-beamed', 24],
161	    ['internet-archive',     'Internet Archive',     'read',        'songbook',             1, 'bi-archive',         30],
162	    ['open-library',         'Open Library',         'read',        'songbook',             1, 'bi-book-half',       31],
163	    ['archive-misc',         'Other archive',        'read',        'song,songbook,person', 1, 'bi-archive',         39],
164	    ['oclc-worldcat',        'WorldCat / OCLC',      'authority',   'songbook',             0, 'bi-card-list',       40],
165	    ['viaf',                 'VIAF authority',       'authority',   'songbook,person',      0, 'bi-card-list',       41],
166	    ['loc-name-authority',   'LoC name authority',   'authority',   'songbook,person',      0, 'bi-card-list',       42],
167	    ['find-a-grave',         'Find a Grave',         'authority',   'person',               0, 'bi-flower2',         43],
168	    ['ccli-songselect',      'CCLI SongSelect',      'purchase',    'song',                 0, 'bi-bag',             50],
169	    ['publisher-store',      'Publisher store',      'purchase',    'songbook',             0, 'bi-shop',            51],
170	    ['imslp',                'IMSLP / Petrucci',     'sheet-music', 'song,songbook,person', 1, 'bi-file-music',      60],
171	    ['sheet-music-pdf',      'Sheet music PDF',      'sheet-music', 'song',                 1, 'bi-file-music',      61],
172	    ['lyrics-page',          'Lyrics page',          'information', 'song',                 1, 'bi-file-text',       25],
173	    ['youtube',              'YouTube',              'watch',       'song,person',          1, 'bi-youtube',         70],
174	    ['vimeo',                'Vimeo',                'watch',       'song,person',          1, 'bi-camera-video',    71],
175	    ['spotify',              'Spotify',              'listen',      'song,person',          1, 'bi-spotify',         80],
176	    ['apple-music',          'Apple Music',          'listen',      'song,person',          1, 'bi-music-note',      81],
177	    ['youtube-music',        'YouTube Music',        'listen',      'song,person',          1, 'bi-music-note',      82],
178	    ['bandcamp',             'Bandcamp',             'listen',      'song,person',          1, 'bi-vinyl',           83],
179	    ['soundcloud',           'SoundCloud',           'listen',      'song,person',          1, 'bi-cloud',           84],
180	    ['librivox',             'LibriVox',             'listen',      'song,songbook',        1, 'bi-mic',             85],
181	    ['discogs',              'Discogs',              'information', 'song,person',          1, 'bi-vinyl',           90],
182	    ['musicbrainz-work',     'MusicBrainz work',     'information', 'song',                 0, 'bi-music-note',      91],
183	    ['musicbrainz-recording','MusicBrainz recording','information', 'song',                 1, 'bi-music-note',      92],
184	    ['musicbrainz-artist',   'MusicBrainz artist',   'information', 'person',               0, 'bi-person-vcard',    93],
185	    ['goodreads-author',     'Goodreads author',     'information', 'person',               0, 'bi-book',            94],
186	    ['linkedin',             'LinkedIn',             'social',      'person',               0, 'bi-linkedin',        100],
187	    ['twitter-x',            'Twitter / X',          'social',      'person',               0, 'bi-twitter-x',       101],
188	    ['instagram',            'Instagram',            'social',      'person',               0, 'bi-instagram',       102],
189	    ['facebook',             'Facebook',             'social',      'person',               0, 'bi-facebook',        103],
190	    ['mastodon',             'Mastodon',             'social',      'person',               0, 'bi-mastodon',        104],
191	    ['other',                'Other',                'other',       'song,songbook,person', 1, 'bi-link-45deg',      999],
192	];
193	
194	$upsert = $mysqli->prepare(
195	    'INSERT INTO tblExternalLinkTypes
196	         (Slug, Name, Category, AppliesTo, AllowMultiple, IconClass, DisplayOrder)
197	     VALUES (?, ?, ?, ?, ?, ?, ?)
198	     ON DUPLICATE KEY UPDATE
199	         Name          = VALUES(Name),
200	         Category      = VALUES(Category),
201	         AppliesTo     = VALUES(AppliesTo),
202	         AllowMultiple = VALUES(AllowMultiple),
203	         IconClass     = VALUES(IconClass),
204	         DisplayOrder  = VALUES(DisplayOrder)'
205	);
206	$seedAdded   = 0;
207	$seedUpdated = 0;
208	foreach ($seedTypes as $t) {
209	    [$slug, $name, $cat, $applies, $multi, $icon, $order] = $t;
210	    $upsert->bind_param('ssssisi', $slug, $name, $cat, $applies, $multi, $icon, $order);
211	    @$upsert->execute();
212	    /* affected_rows is 1 for INSERT, 2 for UPDATE in MySQL's
213	       INSERT…ON DUPLICATE KEY semantics; treat 0 as a no-op
214	       (row already matches the seed exactly). */
215	    $ar = $mysqli->affected_rows;
216	    if ($ar === 1)      $seedAdded++;
217	    elseif ($ar === 2)  $seedUpdated++;
218	}
219	$upsert->close();
220	_migExtLinks_out("[seed] {$seedAdded} link type" . ($seedAdded === 1 ? '' : 's')
221	    . " inserted, {$seedUpdated} updated. Total registry: " . count($seedTypes) . '.');
222	
223	/* ----------------------------------------------------------------------
224	 * Step 3 — tblSongbookExternalLinks
225	 * ---------------------------------------------------------------------- */
226	if (_migExtLinks_tableExists($mysqli, 'tblSongbookExternalLinks')) {
227	    _migExtLinks_out('[skip] tblSongbookExternalLinks already present.');
228	} else {
229	    $sql = "CREATE TABLE tblSongbookExternalLinks (
230	        Id          INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
231	        SongbookId  INT UNSIGNED NOT NULL,
232	        LinkTypeId  INT UNSIGNED NOT NULL,
233	        Url         VARCHAR(2048) NOT NULL,
234	        Note        VARCHAR(255) NULL,
235	        SortOrder   INT UNSIGNED NOT NULL DEFAULT 0,
236	        Verified    TINYINT(1)   NOT NULL DEFAULT 0,
237	        CreatedAt   TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
238	        UpdatedAt   TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
239	
240	        INDEX idx_book (SongbookId),
241	        INDEX idx_type (LinkTypeId),
242	
243	        CONSTRAINT fk_link_book
244	            FOREIGN KEY (SongbookId) REFERENCES tblSongbooks(Id) ON DELETE CASCADE,
245	        CONSTRAINT fk_link_type_book
246	            FOREIGN KEY (LinkTypeId) REFERENCES tblExternalLinkTypes(Id) ON DELETE RESTRICT
247	    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci";
248	    if (!$mysqli->query($sql)) {
249	        throw new \RuntimeException('CREATE TABLE tblSongbookExternalLinks failed: ' . $mysqli->error);
250	    }
251	    _migExtLinks_out('[add ] tblSongbookExternalLinks.');
252	}
253	
254	/* ----------------------------------------------------------------------
255	 * Step 4 — tblSongExternalLinks
256	 * ---------------------------------------------------------------------- */
257	if (_migExtLinks_tableExists($mysqli, 'tblSongExternalLinks')) {
258	    _migExtLinks_out('[skip] tblSongExternalLinks already present.');
259	} else {
260	    $sql = "CREATE TABLE tblSongExternalLinks (
261	        Id          INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
262	        SongId      VARCHAR(20)  NOT NULL,
263	        LinkTypeId  INT UNSIGNED NOT NULL,
264	        Url         VARCHAR(2048) NOT NULL,
265	        Note        VARCHAR(255) NULL,
266	        SortOrder   INT UNSIGNED NOT NULL DEFAULT 0,
267	        Verified    TINYINT(1)   NOT NULL DEFAULT 0,
268	        CreatedAt   TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
269	        UpdatedAt   TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
270	
271	        INDEX idx_song (SongId),
272	        INDEX idx_type (LinkTypeId),
273	
274	        CONSTRAINT fk_link_song
275	            FOREIGN KEY (SongId)     REFERENCES tblSongs(SongId)         ON DELETE CASCADE,
276	        CONSTRAINT fk_link_type_song
277	            FOREIGN KEY (LinkTypeId) REFERENCES tblExternalLinkTypes(Id) ON DELETE RESTRICT
278	    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci";
279	    if (!$mysqli->query($sql)) {
280	        throw new \RuntimeException('CREATE TABLE tblSongExternalLinks failed: ' . $mysqli->error);
281	    }
282	    _migExtLinks_out('[add ] tblSongExternalLinks.');
283	}
284	
285	/* ----------------------------------------------------------------------
286	 * Step 5 — tblCreditPersonExternalLinks
287	 * ---------------------------------------------------------------------- */
288	if (_migExtLinks_tableExists($mysqli, 'tblCreditPersonExternalLinks')) {
289	    _migExtLinks_out('[skip] tblCreditPersonExternalLinks already present.');
290	} else {
291	    $sql = "CREATE TABLE tblCreditPersonExternalLinks (
292	        Id              INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
293	        CreditPersonId  INT UNSIGNED NOT NULL,
294	        LinkTypeId      INT UNSIGNED NOT NULL,
295	        Url             VARCHAR(2048) NOT NULL,
296	        Note            VARCHAR(255) NULL,
297	        SortOrder       INT UNSIGNED NOT NULL DEFAULT 0,
298	        Verified        TINYINT(1)   NOT NULL DEFAULT 0,
299	        CreatedAt       TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
300	        UpdatedAt       TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
301	
302	        INDEX idx_person (CreditPersonId),
303	        INDEX idx_type   (LinkTypeId),
304	
305	        CONSTRAINT fk_link_person
306	            FOREIGN KEY (CreditPersonId) REFERENCES tblCreditPeople(Id)        ON DELETE CASCADE,
307	        CONSTRAINT fk_link_type_person
308	            FOREIGN KEY (LinkTypeId)     REFERENCES tblExternalLinkTypes(Id)   ON DELETE RESTRICT
309	    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci";
310	    if (!$mysqli->query($sql)) {
311	        throw new \RuntimeException('CREATE TABLE tblCreditPersonExternalLinks failed: ' . $mysqli->error);
312	    }
313	    _migExtLinks_out('[add ] tblCreditPersonExternalLinks.');
314	}
315	
316	_migExtLinks_out('External Links migration finished (#833).');
317	_migExtLinks_out('Backfills are separate migrations:');
318	_migExtLinks_out('  - migrate-backfill-songbook-links.php');
319	_migExtLinks_out('  - migrate-backfill-credit-person-links.php');
