90	 * Helpers — link / IPI sub-form normalisation (#719 PR 2d)
91	 *
92	 * The link-type catalogue, the two normalisers, and the
93	 * flag-columns-exist probe now live in
94	 * /includes/credit_people_helpers.php. The closures kept here are
95	 * thin wrappers so the existing call sites below ($normaliseLinks,
96	 * $normaliseIpi, _cpFlagsColumnsExist) keep working unchanged.
97	 * ---------------------------------------------------------------------- */
98	$LINK_TYPE_CATALOGUE = CREDIT_PERSON_LINK_TYPE_CATALOGUE;
99	$LINK_TYPE_KEYS      = CREDIT_PERSON_LINK_TYPE_KEYS;
100	$normaliseLinks      = static fn(mixed $raw): array => normaliseCreditPersonLinks($raw);
101	$normaliseIpi        = static fn(mixed $raw): array => normaliseCreditPersonIpi($raw);
102	
103	/* Wrapper kept under the original snake_case private-prefix name so
104	   existing call sites in this file keep working without further
105	   touch-up. */
106	function _cpFlagsColumnsExist(\mysqli $db): bool
107	{
108	    return creditPeopleFlagsColumnsExist($db);
109	}
