111	/* ----------------------------------------------------------------------
112	 * GET endpoint — view_songs JSON
113	 *
114	 * Returns the list of songs that cite the given person, grouped by
115	 * role. Used by the View Songs modal. Standalone — short-circuits
116	 * the rest of the page (returns JSON, then exit).
117	 *
118	 * GET ?action=view_songs&id=<registry-id>
119	 *
120	 * Looks up the person's name from the registry row, then queries the
121	 * five song-credit tables joined to tblSongs for the human-friendly
122	 * Title + SongbookAbbr + Number used in the modal listing.
123	 * ---------------------------------------------------------------------- */
124	if ($_SERVER['REQUEST_METHOD'] === 'GET' && (string)($_GET['action'] ?? '') === 'view_songs') {
125	    header('Content-Type: application/json; charset=UTF-8');
126	    header('X-Content-Type-Options: nosniff');
127	    header('Cache-Control: no-store');
128	
129	    $personId = (int)($_GET['id'] ?? 0);
130	    if ($personId <= 0) {
131	        http_response_code(400);
132	        echo json_encode(['error' => 'id is required']);
133	        exit;
134	    }
135	
136	    try {
137	        $db = getDbMysqli();
138	        $stmt = $db->prepare('SELECT Name FROM tblCreditPeople WHERE Id = ?');
139	        $stmt->bind_param('i', $personId);
140	        $stmt->execute();
141	        $row = $stmt->get_result()->fetch_row();
142	        $stmt->close();
143	        $name = (string)($row[0] ?? '');
144	        if ($name === '') {
145	            http_response_code(404);
146	            echo json_encode(['error' => 'Person not found.']);
147	            exit;
148	        }
149	
150	        /* For each role table, fetch the songs that cite this name.
151	           Joining to tblSongs on SongId gives us the human-friendly
152	           Title + SongbookAbbr + Number for the modal. */
153	        $tables = [
154	            'writer'     => 'tblSongWriters',
155	            'composer'   => 'tblSongComposers',
156	            'arranger'   => 'tblSongArrangers',
157	            'adaptor'    => 'tblSongAdaptors',
158	            'translator' => 'tblSongTranslators',
159	        ];
160	        $byRole = [];
161	        foreach ($tables as $role => $tbl) {
162	            $sql = "SELECT s.SongId, s.Title, s.SongbookAbbr, s.Number
163	                      FROM {$tbl} c
164	                      JOIN tblSongs s ON s.SongId = c.SongId
165	                     WHERE c.Name = ?
166	                     ORDER BY s.SongbookAbbr ASC, s.Number ASC, s.Title ASC";
167	            $stmt = $db->prepare($sql);
168	            $stmt->bind_param('s', $name);
169	            $stmt->execute();
170	            $byRole[$role] = $stmt->get_result()->fetch_all(MYSQLI_ASSOC);
171	            $stmt->close();
172	        }
173	
174	        echo json_encode([
175	            'name'    => $name,
176	            'by_role' => $byRole,
177	            'total'   => array_sum(array_map('count', $byRole)),
178	        ]);
179	        exit;
180	    } catch (\Throwable $e) {
181	        error_log('[manage/credit-people.php] view_songs failed: ' . $e->getMessage());
182	        logActivityError('admin.credit_people.view_songs', 'credit_person', '', $e);
183	        http_response_code(500);
184	        echo json_encode(['error' => 'Could not load songs.']);
185	        exit;
186	    }
187	}
