+                             w.ParentWorkId AS parentId,
+                             w.Title      AS title,
+                             w.Slug       AS slug,
+                             w.Iswc       AS iswc
+                        FROM tblWorkSongs ws
+                        JOIN tblWorks w ON w.Id = ws.WorkId
+                       WHERE ws.SongId IN ($ph)
+                       ORDER BY w.Title ASC, ws.SortOrder ASC";
+            $stmt  = $this->db->prepare($sql);
+            $types = str_repeat('s', count($clean));
