+                    'slug'        => (string)$row['slug'],
+                    'iswc'        => (string)($row['iswc'] ?? ''),
+                    'isCanonical' => (bool)$row['isCanonical'],
+                    'memberNote'  => (string)($row['memberNote'] ?? ''),
