+            $stmt2->execute();
+            $r2 = $stmt2->get_result();
+            $membersByWork = [];
+            while ($mrow = $r2->fetch_assoc()) {
+                $wid = (int)$mrow['workId'];
+                $membersByWork[$wid][] = [
+                    'songId'       => (string)$mrow['songId'],
+                    'title'        => (string)$mrow['title'],
