+                            t.Category  AS category,
+                            t.IconClass AS iconClass,
+                            el.Url      AS url,
+                            el.Note     AS note,
+                            el.Verified AS verified,
+                            el.SortOrder AS sortOrder
+                       FROM {$table} el
+                       JOIN tblExternalLinkTypes t ON t.Id = el.LinkTypeId
