+         * ----------------------------------------------------------------- */
+        case 'regions':
+            $db = getDbMysqli();
+            $hasTable = false;
+            try {
+                $probe = $db->prepare(
+                    "SELECT 1 FROM INFORMATION_SCHEMA.TABLES
