+            $stmt->close();
+            if (!$sourceSong) {
+                sendJson(['error' => 'Song not found.'], 404);
+                break;
+            }
+
+            $related = [];
+            $seenIds = [$songId => true];
+
+            /* 1. Songs by the same writer(s) */
