+            $stmt = $db->prepare(
+                'SELECT SongId FROM tblUserFavorites WHERE UserId = ? ORDER BY CreatedAt DESC'
+            );
+            $stmt->bind_param('i', $userId);
+            $stmt->execute();
+            $finalFavs = array_column($stmt->get_result()->fetch_all(MYSQLI_ASSOC), 'SongId');
+            $stmt->close();
