+            $songId = isset($_GET['id']) ? trim($_GET['id']) : '';
+            $relLimit = isset($_GET['limit']) ? min((int)$_GET['limit'], 50) : 10;
+
+            if ($songId === '' || !preg_match('/^[A-Za-z]+-\d+$/', $songId)) {
+                sendJson(['error' => 'Valid song ID is required.'], 400);
