+                $seenIds[$row['id']] = true;
+                $row['number'] = (int)$row['number'];
+                $row['reason'] = 'Same composer: ' . $row['reason'];
+                $related[] = $row;
+            }
+            $stmt->close();
+
+            /* 3. Songs with shared tags */
+            $stmt = $db->prepare(
+                'SELECT DISTINCT s.SongId AS id, s.Title AS title, s.SongbookAbbr AS songbook,
+                        s.Number AS number, t.Name AS reason
