+                 JOIN tblSongTagMap tm2 ON tm2.TagId = tm1.TagId AND tm2.SongId != tm1.SongId
+                 JOIN tblSongs s ON s.SongId = tm2.SongId
+                 JOIN tblSongTags t ON t.Id = tm1.TagId
+                 WHERE tm1.SongId = ?
