+            sendJson([
+                'database_up'           => true,
+                'table_counts'          => $tableCounts,
+                'songs_json_fallback'   => $songDataJsonFallback,
+                'songs_json_note'       => $songDataNote,
+                'share_dir' => [
+                    'configured'        => $shareDirPath !== '',
+                    'present'           => $shareDirPath !== '' && is_dir($shareDirPath),
