+                                  'placeholder="https://…" value="' + escapeHtml(url) + '">' +
+                        '</div>' +
+                      '</div>' +
+                      '<div class="row g-2">' +
+                        '<div class="col-md-9">' +
+                          '<input type="text" class="form-control form-control-sm" ' +
