+                a.onclick = (ev) => {
+                    ev.preventDefault();
+                    let payload;
+                    try { payload = JSON.parse(a.getAttribute('data-payload')); } catch (_e) { return; }
+                    /* skip if already in the list */
+                    if (tbody.querySelector('tr[data-song-id="' + (payload.songId || '').replace(/"/g, '\\"') + '"]')) {
+                        sugBox.style.display = 'none';
+                        search.value = '';
