+                    linkRowsEl.appendChild(buildLinkRow({
+                        typeId: l.typeId, url: l.url, note: l.note, verified: l.verified,
+                    }));
+                });
+            }
+
+            if (sugBox) { sugBox.style.display = 'none'; sugBox.innerHTML = ''; }
