+            $next = [];
+            foreach ($frontier as $parentId) {
+                $stmt->bind_param('i', $parentId);
+                $stmt->execute();
+                $res = $stmt->get_result();
+                while ($row = $res->fetch_row()) {
+                    $cid = (int)$row[0];
+                    if (!isset($descendants[$cid])) {
+                        $descendants[$cid] = true;
+                        $next[] = $cid;
+                    }
+                }
+            }
+            $frontier = $next;
+            $depth++;
+        }
+        $stmt->close();
+    }
