+            const registry = [];
+            document.querySelectorAll('#cp-tbody tr[data-person]').forEach(r => {
+                let p; try { p = JSON.parse(r.getAttribute('data-person')); } catch (_) { return; }
+                if (p.registry_id) {
+                    registry.push({ id: p.registry_id, name: p.name, key: 'id:' + p.registry_id });
