+        SELECT p.Id,
+               p.Name,
+               p.Notes,
+               p.BirthPlace,
+               p.BirthDate,
+               p.DeathPlace,
+               p.DeathDate,
+               p.UpdatedAt,
+               (SELECT COUNT(*) FROM tblCreditPersonLinks l WHERE l.CreditPersonId = p.Id) AS LinkCount,
