+                const row = btn.closest('tr');
+                if (!row) return;
+                const raw = row.getAttribute('data-person');
+                if (!raw) return;
+                let person; try { person = JSON.parse(raw); } catch (_) { return; }
+                /* In-use-only rows pass through too (#626) — the
