+    try {
+        $like = '%' . $q . '%';
+        /* Identifier built from the allowlisted probe above — never
+           user input, so no SQL injection surface. */
+        $stmt = $db->prepare(
+            "SELECT Code AS code, Name AS name, NativeName AS nativeName
+               FROM {$tableName}
+              WHERE IsActive = 1
+                AND (Name LIKE ? OR Code LIKE ?)
+              ORDER BY Name ASC
+              LIMIT ?"
+        );
