+            tr.addEventListener('dragend', () => {
+                if (draggedRow) draggedRow.classList.remove('dragging');
+                draggedRow = null;
+                tr.draggable = false;
+                clearDropMarkers();
+                renumber();
+            });
+        });
+    })();
+    </script>
