+           Other-language articles (Spanish "El", French "Le/La", …)
+           are out of scope for v1; flag in the issue comment if a
+           curator hits the limit (#674). */
+        const stripArticle = (s) =>
+            (s || '').replace(/^\s*(the|an|a)\s+/i, '').toLowerCase();
