+ * ----------------------------------------------------------------------- */
+if (($_SERVER['REQUEST_METHOD'] ?? 'GET') === 'GET'
+    && ($_GET['action'] ?? '') === 'pick_colour'
+) {
+    header('Content-Type: application/json; charset=UTF-8');
