+                  + escapeHtml(nm) + ' <i class="bi bi-box-arrow-up-right small" aria-hidden="true"></i></a>'
+                : escapeHtml(nm);
+            card.innerHTML =
+                '<div class="card-body py-2">' +
+                  '<div class="d-flex align-items-center gap-2">' +
+                    '<i class="bi bi-grip-vertical text-muted" aria-hidden="true"></i>' +
