check('https://en.wikipedia.org/wiki/Foo',                            'wikipedia');    /* fallback */
check('https://www.youtube.com/watch?v=abc',                          'youtube');      /* fallback */

/* Output. */
console.log(`\n#841 + #845 external-link-detect: ${passed} passed, ${failed} failed.`);
