+            $score = _cpBulkSimilarity($c['name'], (string)$r['Name']);
+            if ($score >= $threshold) {
+                $c['matches'][] = [
+                    'id'    => (int)$r['Id'],
+                    'name'  => (string)$r['Name'],
+                    'score' => round($score, 3),
+                ];
+            }
+        }
+        usort($c['matches'], static fn($a, $b) => $b['score'] <=> $a['score']);
+    }
