+ * $db->begin_transaction() so a partial failure (e.g. a child-row
+ * INSERT failing after the parent UPDATE landed) rolls back cleanly.
+ * ---------------------------------------------------------------------- */
+if ($_SERVER['REQUEST_METHOD'] === 'POST') {
+    if (!validateCsrf((string)($_POST['csrf_token'] ?? ''))) {
