+$totalInRegistry      = count(array_filter($people, static fn($p) => $p['registry_id'] !== null));
+$totalInUse           = count(array_filter($people, static fn($p) => $p['total'] > 0));
+$totalRegistryOnly    = $totalNames - $totalInUse;
