1266	        /* Run pending-probes against the live schema (#820). Uses the
1267	           same connection we just opened — a single round trip per
1268	           probe, all under 100 ms cumulatively on a typical install.
1269	           Any throw / unknown probe falls into "pending" so the card
1270	           still appears (over-show is safe; under-hide is not). */
1271	        $pendingActions = [];
1272	        $appliedActions = [];
1273	        foreach ($migrationOrder as $_action) {
1274	            $_probe = $migrationProbes[$_action] ?? null;
1275	            if ($_probe === null) {
1276	                $pendingActions[] = $_action;
1277	                continue;
1278	            }
1279	            try {
1280	                if ($_probe($statusConn)) {
